patches.content:
/* v0.18.2 — A-plan mobile poster-first hero */
@media(max-width:720px){
  .topbar .nav{
    height:60px;
    gap:9px;
  }
  .brand{
    gap:9px;
    font-size:18px;
    white-space:nowrap;
    min-width:0;
  }
  .mark{
    width:30px;
    height:30px;
    flex:0 0 30px;
  }
  .mobile-search{
    margin-left:auto;
    padding:8px 10px;
    border:1px solid #504b43;
    border-radius:2px;
    background:transparent;
    color:#eee9df;
    font-size:11px;
    font-weight:800;
  }
  .nav-actions{
    margin-left:0;
    gap:6px;
  }
  .nav-actions #searchBtn{
    display:none!important;
  }
  .nav-actions .primary.compact{
    padding:8px 10px;
    font-size:11px;
  }
  .topbar .nav:after{
    width:44px;
  }

  .hero{
    display:grid;
    grid-template-columns:1fr!important;
    gap:0;
    padding:18px 0 28px;
  }
  .hero-card{
    display:flex;
    flex-direction:column;
    min-height:0;
    overflow:visible;
    background:transparent;
    border-bottom:1px solid #4a453d;
  }
  .hero-backdrop{
    position:relative;
    inset:auto;
    width:100%;
    aspect-ratio:2/3;
    min-height:0;
    transform:none;
    background-size:cover;
    background-position:center 22%;
  }
  .hero-backdrop:after{
    background:linear-gradient(0deg,rgba(8,8,7,.30) 0,rgba(8,8,7,.09) 24%,transparent 48%);
  }
  .hero-copy{
    position:relative;
    left:auto;
    right:auto;
    bottom:auto;
    width:100%;
    max-width:none;
    padding:18px 0 22px;
    background:none;
  }
  .hero .kicker{
    font-size:9px;
    letter-spacing:.18em;
  }
  .hero h1{
    max-width:12ch;
    margin:8px 0 12px;
    font-size:clamp(38px,11.5vw,48px);
    line-height:.96;
    letter-spacing:-.06em;
    text-wrap:balance;
    word-break:keep-all;
  }
  .hero h1 br{
    display:none;
  }
  .hero p{
    display:-webkit-box;
    max-width:34em;
    margin:0;
    color:#bdb7ad;
    font-size:14px;
    line-height:1.65;
    -webkit-box-orient:vertical;
    -webkit-line-clamp:3;
    overflow:hidden;
  }
  .hero-actions{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:8px;
    margin-top:18px;
  }
  .hero-actions .primary,
  .hero-actions .ghostbtn{
    width:100%;
    padding:11px 10px;
    text-align:center;
  }

  .stat-stack{
    display:grid;
    grid-template-columns:1fr 1fr;
    grid-template-rows:none;
    gap:0;
    margin-top:16px;
    border-top:1px solid #3b3831;
    border-bottom:1px solid #3b3831;
  }
  .stat{
    min-height:0;
    padding:15px 12px 16px 0;
    border:0!important;
    background:transparent!important;
  }
  .stat + .stat{
    padding-left:12px;
    padding-right:0;
    border-left:1px solid #3b3831!important;
  }
  .stat .big{
    font-size:26px;
    line-height:1;
    font-weight:500;
  }
  .stat h3{
    margin:7px 0 6px;
    font-size:15px;
    line-height:1.25;
    letter-spacing:-.035em;
  }
  .stat p{
    display:-webkit-box;
    margin:0;
    color:#8f897f;
    font-size:10.5px;
    line-height:1.5;
    -webkit-box-orient:vertical;
    -webkit-line-clamp:3;
    overflow:hidden;
  }
  .stat .kicker{
    font-size:8px;
    letter-spacing:.17em;
  }

  .data-strip{
    display:grid;
    grid-template-columns:auto 1fr;
    gap:6px 9px;
    padding:10px 0;
    font-size:10.5px;
  }
  .data-strip .right{
    grid-column:2;
    margin-left:0;
    color:#777168;
  }

  .poster-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:24px 12px;
  }
  .poster-wrap{
    aspect-ratio:2/3;
  }
  .poster-copy{
    padding-top:10px;
  }
  .poster-copy h3{
    display:-webkit-box;
    margin:3px 0 6px;
    font-size:15px;
    line-height:1.25;
    letter-spacing:-.035em;
    word-break:keep-all;
    -webkit-box-orient:vertical;
    -webkit-line-clamp:2;
    overflow:hidden;
  }
  .poster-copy p{
    display:none;
  }
  .poster-next{
    margin-top:9px;
    padding-top:7px;
    font-size:10px;
  }
}
@media(max-width:420px){
  .wrap{width:calc(100% - 28px)}
  .brand{font-size:17px}
  .hero h1{font-size:42px}
  .hero p{font-size:13.5px}
  .stat h3{font-size:14px}
  .poster-grid{gap:22px 10px}
}
